import React, { useEffect, useState } from 'react';
import classNames from 'classnames';
import { OverlayTrigger, Popover } from 'react-bootstrap';
import ButtonGroupComponent from '../button-group/index';
import ClickableDiv from '../../atoms/clickableDiv';
import Text from '../../atoms/text/index';
import {
  LanguagePayload,
  LanguageItem,
  SizeEnum,
  AlignEnum,
  ColorNameEnum,
  WeightEnum,
} from '../../types';
import './index.less';

function LanguageSelector({
  selectedLanguage,
  value,
  items,
  onLanguageChange,
  disabled,
  filterButtonStyle = false,
}: LanguagePayload) {
  const [languageIndex, setLanguageIndex] = useState(selectedLanguage);
  const [displayedLanguage, setDisplayedLanguage] = useState<LanguageItem>();
  const [show, setShow] = useState(false);

  useEffect(() => {
    const language = items.find((item: any) => item.value === languageIndex);
    setDisplayedLanguage(language);
  }, [items, languageIndex]);

  return (
    <>
      <OverlayTrigger
        trigger="click"
        rootClose
        placement="bottom-start"
        show={show && !disabled}
        overlay={
          <Popover
            className={classNames('language-dropdown-popover btn-group-dropdown-popover', {
              'filter-btn-style': filterButtonStyle,
            })}
            id="popover"
          >
            <div className="popover-content">
              <ButtonGroupComponent
                searchable
                bgColor="default"
                buttonType="dropdownOption"
                width="block"
                direction="column"
                color="extraDarkGray"
                onChange={(filterValue) => {
                  setLanguageIndex(filterValue);
                  if (onLanguageChange) onLanguageChange(filterValue);
                  setShow(!show);
                }}
                multiLines
                value={value}
                items={items}
              />
            </div>
          </Popover>
        }
      >
        {filterButtonStyle ? (
          <ClickableDiv
            onClick={() => setShow(!show)}
            className={classNames('language-selector-btn', { 'popover-opened': show })}
            tooltip-data={displayedLanguage?.text ?? ''}
            disabled={disabled}
          >
            <Text
              size={SizeEnum['12px']}
              align={AlignEnum.left}
              weight={WeightEnum.normal}
              colorName={ColorNameEnum.ultraDark}
              text="Language:"
              inline
            />
            &nbsp;
            <Text
              className="language-text"
              size={SizeEnum['12px']}
              align={AlignEnum.left}
              weight={WeightEnum.bold}
              colorName={ColorNameEnum.ultraDark}
              text={displayedLanguage?.text ?? ''}
              inline
            />
            <Text
              align={AlignEnum.left}
              colorName={ColorNameEnum.theme}
              className="arrow-icon icon-chevron-down"
              inline
            />
          </ClickableDiv>
        ) : (
          <ClickableDiv
            onClick={() => setShow(!show)}
            className="language-selector-wrap"
            tooltip-data={displayedLanguage?.text ?? ''}
            disabled={disabled}
          >
            <Text
              size={SizeEnum['14px']}
              align={AlignEnum.left}
              weight={WeightEnum.light}
              colorName={ColorNameEnum.theme}
              className="language-icon icon-lang"
              inline
            />
            <Text
              className="language-text"
              size={SizeEnum['12px']}
              align={AlignEnum.left}
              colorName={ColorNameEnum.theme}
              text={displayedLanguage?.text ?? ''}
              inline
            />
            <Text
              size={SizeEnum['12px']}
              align={AlignEnum.left}
              colorName={ColorNameEnum.theme}
              className="arrow-icon icon-chevron-down"
              inline
            />
          </ClickableDiv>
        )}
      </OverlayTrigger>
    </>
  );
}

export default LanguageSelector;
